"""Task-local inspection: find .db files in the workspace and print their schemas."""

import sqlite3
from pathlib import Path


def main() -> None:
    db_files = sorted(Path(".").rglob("*.db"))
    if not db_files:
        print("NO_DB_FILES")
        return
    for db_path in db_files:
        print(f"DB: {db_path}")
        with sqlite3.connect(db_path) as conn:
            conn.row_factory = sqlite3.Row
            tables = conn.execute(
                "SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name"
            ).fetchall()
            for table in tables:
                name = table["name"]
                print(f"  TABLE: {name}")
                for col in conn.execute(f'PRAGMA table_info("{name}")'):
                    print(
                        f"    {col['name']} {col['type']} "
                        f"notnull={col['notnull']} default={col['dflt_value']!r} pk={col['pk']}"
                    )


if __name__ == "__main__":
    main()

"""Task-local inspection: list indexes on the users table of user_credentials.db."""

import sqlite3
from pathlib import Path

DB_PATH = Path(__file__).parent / "user_credentials.db"


def main() -> None:
    with sqlite3.connect(DB_PATH) as conn:
        conn.row_factory = sqlite3.Row
        indexes = conn.execute(
            "SELECT name, sql FROM sqlite_master WHERE type = 'index' AND tbl_name = 'users'"
        ).fetchall()
        if not indexes:
            print("NO_INDEXES")
        for idx in indexes:
            print(f"INDEX: {idx['name']} -> {idx['sql']}")


if __name__ == "__main__":
    main()

